INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(118089, 'ruRU', '', 'Используй Отравление!', 24330),
(118090, 'ruRU', '', 'У тебя 5 очков комбо. Используй Отравление!', 24330),
(118091, 'ruRU', '', 'Используй Алый пузырёк, чтобы восстановить здоровье!', 24330),
(118092, 'ruRU', '', 'Отлично сделано, $p! Теперь ты готов сражаться как разбойник-убийца.', 24330),
(118093, 'ruRU', '', 'Покажи мне, что у тебя есть всё необходимое, $p!', 24330),
(118094, 'ruRU', '', 'Используй Веер клинков, чтобы расправиться с этой группой врагов.', 24330),
(118095, 'ruRU', '', 'Веер клинков обрушивает урон на всех врагов, окружающих тебя. Он также даёт очко комбо за каждого поражённого врага.', 24330),
(118096, 'ruRU', '', 'Враги, что попытаются окружить тебя, получат неприятный сюрприз!', 24330),
(118097, 'ruRU', '', 'Используй Шаг сквозь тень, чтобы появиться за спиной далёкой цели.', 24330),
(118098, 'ruRU', '', 'Используя Шаг сквозь тень, ты останешься в скрытности, готовый нанести удар.', 24330),
(118099, 'ruRU', '', 'Иногда тебе может понадобиться приблизиться к цели, но не наносить урон сразу же.', 24330),
(118100, 'ruRU', '', 'Используй Алый пузырёк, чтобы восстановить часть своего здоровья.', 24330),
(118101, 'ruRU', '', 'Алый пузырёк — алхимическое зелье, которое восстановит часть твоего здоровья.', 24330),
(118102, 'ruRU', '', 'Ты получил некоторый урон, но, к счастью, хитроумный разбойник планирует наперёд.', 24330),
(118103, 'ruRU', '', 'Используй Отравление с 5 очками комбо.', 24330),
(118104, 'ruRU', '', 'Если твоя цель уже поражена Разрывом, то использование Отравления с 5 очками комбо наносит хороший урон и максимизирует эффект твоих ядов.', 24330),
(118105, 'ruRU', '', 'Разрыв — не единственный твой завершающий приём.', 24330),
(118106, 'ruRU', '', 'Используй Разрыв с 5 очками комбо.', 24330),
(118107, 'ruRU', '', 'Когда ты используешь Разрыв с 5 очками комбо, ты наносишь мощную кровоточащую атаку, что повреждает врагов с течением времени.', 24330),
(118108, 'ruRU', '', 'Теперь, когда у тебя накоплено 5 очков комбо, время использовать Разрыв.', 24330),
(118109, 'ruRU', '', 'Используй Увечье, чтобы атаковать тренировочный манекен.', 24330),
(118110, 'ruRU', '', 'Твоя основная атака называется Увечье. Она наносит урон, а также даёт очки комбо, которые можно использовать для мощных завершающих приёмов.', 24330),
(118111, 'ruRU', '', 'Всегда помни об использовании Удушения, чтобы твои враги продолжали кровоточить.', 24330),
(118112, 'ruRU', '', 'Используй Удушение на этом тренировочном манекене.', 24330),
(118113, 'ruRU', '', 'Лучший способ начать бой — с Удушения, истощающей кровоточащей атаки, что заставляет врага получать урон с течением времени.', 24330),
(118114, 'ruRU', '', 'Будучи убийцей, ты ослабляешь врагов, прежде чем прикончить их.', 24330),
(118115, 'ruRU', '', 'Используй Скрытность, чтобы исчезнуть из поля зрения.', 24330),
(118116, 'ruRU', '', 'Скрытность делает тебя невидимым для большинства врагов. В Скрытности ты можешь приблизиться к врагам незамеченным.', 24330),
(118117, 'ruRU', '', 'Убийцы предпочитают хитрость и коварство. А что может быть хитрее, чем атаковать, прежде чем цель заметит твоё приближение?', 24330),
(118118, 'ruRU', '', 'Используй Смертельный яд, чтобы покрыть своё оружие ядом на один час.', 24330),
(118119, 'ruRU', '', 'Прежде чем начать, нам нужно нанести яд на твоё оружие.', 24330),
(118120, 'ruRU', '', 'Будучи разбойником-убийцей, ты специализируешься на ударах из теней, расправляясь с врагами с помощью разнообразных ядов и кровоточащих атак.', 24330),
(118121, 'ruRU', '', 'Используй Огненного элементаля прямо сейчас, чтобы призвать своего элементаля!', 24330),
(118122, 'ruRU', '', 'Будучи повелителем стихий, ты способен сплавить первородные силы стихий в физическую форму, чтобы помочь тебе в бою.', 24330),
(118123, 'ruRU', '', 'Используй Волну исцеления, чтобы полностью восполнить своё здоровье.', 24330),
(118124, 'ruRU', '', 'Как стихии способны разрушать, так и они обладают силой восстанавливать.', 24330),
(118125, 'ruRU', '', 'Ты получил урон, но для тебя это не проблема.', 24330),
(118126, 'ruRU', '', 'Используй Цепь молний против нескольких врагов одновременно.', 24330),
(118127, 'ruRU', '', 'Когда ты поражаешь врага Цепью молний, она перескакивает на дополнительных врагов рядом с твоей целью, нанося урон всем им.', 24330),
(118128, 'ruRU', '', 'Бывают моменты, когда тебе придётся сражаться с несколькими противниками на поле боя. К счастью, у тебя есть мощная способность под названием Цепь молний.', 24330);
